CREATE TABLE IF NOT EXISTS ProcessingJobs(Id VARCHAR(100) PRIMARY KEY, SourceAssetId VARCHAR(100) NOT NULL, SourceSha256 CHAR(64) NOT NULL, Operation VARCHAR(32) NOT NULL, SettingsJson TEXT NOT NULL, SettingsHash CHAR(64) NOT NULL, Status VARCHAR(20) NOT NULL, Stage VARCHAR(255) NOT NULL, Progress DOUBLE NOT NULL, LogsJson LONGTEXT NOT NULL, ResultJson LONGTEXT NULL, Error TEXT NOT NULL, CancelRequested BOOLEAN NOT NULL, CreatedAt VARCHAR(40) NOT NULL, UpdatedAt VARCHAR(40) NOT NULL, INDEX(Status,CreatedAt));
